use std::fs;

pub fn soak(files: &[(i32, String)], dest_dir: &str) -> Result<(), i32> {
    match fs::remove_dir_all(dest_dir) {
        Ok(()) => {}
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
        Err(_) => return Err(1),
    }
    fs::create_dir_all(dest_dir).map_err(|_| 1)?;

    let mut ordered = files.to_vec();
    ordered.sort_by_key(|x| x.0);
    for (day, source) in ordered {
        let dest = format!("{}/d{:08}.tbl", dest_dir, day);
        fs::copy(source, dest).map_err(|_| 1)?;
    }
    Ok(())
}
