#[path = "../hopcue/rim.rs"]
mod rim;
#[path = "../restpit/soak.rs"]
mod soak;
#[path = "../shardfold/read.rs"]
mod read;

use std::fs;

fn clear_dir(path: &str) -> Result<(), i32> {
    match fs::remove_dir_all(path) {
        Ok(()) => {}
        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
        Err(_) => return Err(1),
    }
    fs::create_dir_all(path).map_err(|_| 1)
}

pub fn fold() -> Result<(Vec<(i32, String)>, i32), i32> {
    let wall: i32 = fs::read_to_string("/app/opstext/WALL")
        .map_err(|_| 1)?
        .trim()
        .parse()
        .map_err(|_| 1)?;

    let picked = rim::rim(wall, read::list("/app/daywell"));
    clear_dir("/app/packbay/stage")?;
    clear_dir("/app/packbay/latest")?;
    if picked.is_empty() {
        return Err(1);
    }

    let mut packed = Vec::new();
    let mut taken = 0i32;
    for (day, source) in picked {
        let text = fs::read_to_string(&source).map_err(|_| 1)?;
        let rows = text.lines().filter(|line| !line.trim().is_empty()).count() as i32;
        let stage = format!("/app/packbay/stage/d{:08}.tbl", day);
        fs::copy(&source, stage).map_err(|_| 1)?;
        taken = taken.checked_add(rows).ok_or(1)?;
        packed.push((day, source));
    }
    if taken == 0 {
        clear_dir("/app/packbay/stage")?;
        return Err(1);
    }

    soak::soak(&packed, "/app/packbay/latest")?;
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write(
        "/app/bloturn/ledger.json",
        format!("{{\"taken\":{}}}", taken),
    )
    .map_err(|_| 1)?;
    Ok((packed, taken))
}
EOF

