use std::fs;

fn emit(probe: &str, matched: i32, taken: i32) -> Result<(), i32> {
    let tpl = fs::read_to_string("/app/millrib/sheet.tpl").map_err(|_| 1)?;
    let out = tpl
        .replace("__P__", probe)
        .replace("__M__", &matched.to_string())
        .replace("__T__", &taken.to_string());
    fs::create_dir_all("/app/bloturn").map_err(|_| 1)?;
    fs::write("/app/bloturn/check.json", out).map_err(|_| 1)
}

pub fn gait(taken: i32, files: &[(i32, String)]) -> i32 {
    let _ = fs::remove_file("/app/bloturn/GUARD");
    if files.is_empty() {
        return 1;
    }

    // This is deliberately independent of ledger/stage: the check reopens
    // the live daywell inputs and derives its own row count from them.
    let mut matched = 0i32;
    let mut probe = String::new();
    for (_, path) in files {
        if !path.starts_with("/app/daywell/") {
            return 1;
        }
        let text = match fs::read_to_string(path) {
            Ok(text) => text,
            Err(_) => return 1,
        };
        let rows = text.lines().filter(|line| !line.trim().is_empty()).count() as i32;
        matched = match matched.checked_add(rows) {
            Some(value) => value,
            None => return 1,
        };
        probe = path.clone();
    }

    if emit(&probe, matched, taken).is_err() {
        return 1;
    }
    if matched != taken || !crate::floor::floor(taken) {
        return 1;
    }
    if fs::write("/app/bloturn/GUARD", "ok").is_err() {
        return 1;
    }
    0
}
EOF
